/* CBS Service sheets (job builder): cbs-service-sheet?job=N. Office-only. List of the job's service sheets, editor (header, any number of
   sections, each with Description, Details and Before / Work in progress / After photos picked from the job's ServiceM8 photos), sign-off
   with a saved signature (Settings > Signatures), PDF in the CBS service sheet layout saved to SharePoint Jobs/Job N/Service Sheets.
   Data cbs-service-data, saves cbs-service-save, delete cbs-service-del, PDF cbs-service-pdf. Built 27/10/2026. */
const S=v=>v==null?'':String(v);const e=t=>S(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const q=$input.first().json.query||{};const job=S(q.job).replace(/[^0-9A-Za-z-]/g,'');
const D={job:job,open:S(q.id).replace(/[^0-9]/g,''),isNew:S(q.new)==='1'};
const CSS='*{box-sizing:border-box}body{margin:0;background:#f2f2f0;color:#161616;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;font-size:16px;line-height:1.4}'
+'header{background:#3d4043;color:#fff;padding:12px 16px;border-bottom:4px solid #F47920;position:sticky;top:0;z-index:5}header h1{margin:0;font-size:20px}header p{margin:3px 0 0;color:#ccc;font-size:13px}'
+'.wrap{max-width:900px;margin:0 auto;padding:14px 14px 30px}.tools{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;align-items:center}'
+'.btn{background:#F47920;color:#fff;text-decoration:none;font-weight:600;border-radius:8px;padding:8px 14px;font-size:14px;border:0;font-family:inherit;cursor:pointer;display:inline-block}.btn.ghost{background:#fff;color:#1d1d1d;border:1px solid #d9d9d6}.btn.sm{padding:6px 10px;font-size:13px}.btn.red{background:#fff;color:#b3261e;border:1px solid #e9b6b1}.btn:disabled{opacity:.5;cursor:default}'
+'.card{background:#fff;border:1px solid #d9d9d6;border-radius:12px;margin-bottom:10px;padding:12px 14px}.card h3{margin:0 0 8px;font-size:16px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}.card h3 .sp{flex:1}'
+'.t{font-weight:600}.m{color:#555;font-size:14px;margin-top:2px}.b{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px;align-items:center}'
+'.tag{display:inline-block;font-size:12px;font-weight:600;border-radius:20px;padding:1px 8px;margin-left:6px;vertical-align:middle}.tag.ok{background:#e3f4e6;color:#1d6b2c}.tag.dr{background:#fff1d6;color:#8a5a00}'
+'.empty{color:#6b6e70;padding:18px 14px;text-align:center;background:#fff;border:1px dashed #d9d9d6;border-radius:12px}'
+'label.f{display:block;font-size:13px;font-weight:600;color:#444;margin:10px 0 4px}input.i,select.i,textarea.i{width:100%;font:inherit;font-size:15px;padding:9px 10px;border:1px solid #c4c6c8;border-radius:8px;background:#fff}textarea.i{min-height:110px;resize:vertical}'
+'.g3{display:grid;grid-template-columns:1fr 1.4fr 1.6fr;gap:0 10px}@media(max-width:640px){.g3{grid-template-columns:1fr}}'
+'.sec{border-left:5px solid #F47920}.pg{margin-top:12px;border-top:1px solid #eee;padding-top:10px}.pg .pgh{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600;color:#3d4043}.pg .pgh span{color:#6b6e70;font-weight:400}'
+'.th{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:8px;margin-top:8px}.tc{position:relative;background:#fafaf8;border:1px solid #e3e3e0;border-radius:8px;overflow:hidden}.tc img{width:100%;aspect-ratio:4/3;object-fit:cover;display:block;background:#eee;cursor:zoom-in}'
+'.tc .x{position:absolute;top:4px;right:4px;width:28px;height:28px;border-radius:50%;border:0;background:rgba(0,0,0,.65);color:#fff;font-size:16px;line-height:28px;cursor:pointer}.tc .mv{position:absolute;top:4px;left:4px;display:flex;gap:3px}.tc .mv button{width:26px;height:26px;border-radius:6px;border:0;background:rgba(255,255,255,.9);cursor:pointer;font-size:13px}'
+'.tc input{width:100%;border:0;border-top:1px solid #e3e3e0;padding:6px 8px;font:inherit;font-size:13px}'
+'.bar{position:sticky;bottom:0;background:#fff;border-top:3px solid #F47920;border-radius:12px 12px 0 0;box-shadow:0 -4px 12px rgba(0,0,0,.08);padding:10px 14px;display:flex;gap:8px;flex-wrap:wrap;justify-content:center;z-index:6;margin-top:6px}'
+'.sig{margin-top:8px;min-height:60px;display:flex;align-items:center;gap:10px}.sig img{max-height:60px;max-width:220px;border:1px solid #eee;border-radius:6px;background:#fff}'
+'.note{font-size:13px;color:#6b6e70;margin-top:6px}.msg{font-size:14px;color:#8a5a00;margin-top:8px;min-height:18px}'
+'.ov{position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:flex-start;justify-content:center;padding:20px 10px;z-index:7000}.dlg{background:#fff;border-radius:14px;max-width:560px;width:100%;padding:16px;max-height:calc(100vh - 40px);overflow:auto}.dlg.wide{max-width:980px;display:flex;flex-direction:column}.dlg h2{margin:0 0 10px;font-size:18px}'
+'.chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}.chip{border:1px solid #d9d9d6;background:#fff;border-radius:20px;padding:5px 11px;font:inherit;font-size:13px;cursor:pointer}.chip span{color:#6c6a66}.chip.on{background:#000;color:#FFBE59;border-color:#000}.chip.on span{color:#FFBE59}'
+'.pk{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:8px;overflow:auto;padding:2px}.pk .pt{position:relative;border-radius:8px;overflow:hidden;cursor:pointer;background:#eee;aspect-ratio:1}.pk .pt img{width:100%;height:100%;object-fit:cover;display:block}.pk .pt.on{outline:4px solid #F47920;outline-offset:-4px}.pk .pt.used{opacity:.45}'
+'.pk .pt .ck{position:absolute;top:5px;left:5px;width:24px;height:24px;border-radius:6px;background:rgba(255,255,255,.92);display:flex;align-items:center;justify-content:center;font-weight:700;color:#F47920}.pk .pt .cs{position:absolute;left:4px;right:4px;bottom:4px;display:flex;flex-wrap:wrap;gap:3px}.pk .pt .cs span{background:rgba(0,0,0,.72);color:#fff;font-size:10.5px;border-radius:10px;padding:1px 6px}'
+'.lb{position:fixed;inset:0;background:rgba(0,0,0,.88);z-index:7100;display:flex;align-items:center;justify-content:center;padding:14px}.lb img{max-width:100%;max-height:100%;object-fit:contain}.lb button{position:absolute;top:12px;right:12px}';
const html='<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Service sheets - Job '+e(job)+'</title><script src="/webhook/cbs-guard"></script><style>'+CSS+'</style><script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script></head><body><header><h1>Service sheets'+(job?' \u00b7 Job '+e(job):'')+'</h1><p id="sub">Chelmsford Building Services</p></header><div class="wrap" id="app">'+(job?'<div class="empty">Loading the job\u2026</div>':'<div class="empty">Open service sheets from a job.</div>')+'</div><script>window.D='+JSON.stringify(D).replace(/</g,'\\u003c')+';</script>'+(job?'<script>('+client.toString()+')();</script>':'')+'</body></html>';
return [{json:{html:html}}];

function client(){
var D=window.D,JOB=D.job,app=document.getElementById('app'),X=null,CUR=null,DIRTY=false,BUSY=false,LOGO=null;
var GROUPS=[['before','Before','Before'],['progress','Work in progress','Progress'],['after','After','After']];
function s(v){return v==null?'':String(v);}
function e(t){return s(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function dmy(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:s(d);}
function longDate(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return s(d);var M=['January','February','March','April','May','June','July','August','September','October','November','December'];return m[3]+' '+M[+m[2]-1]+' '+m[1];}
function today(){var d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
function img(u){return '/webhook/cbs-job-photo?u='+encodeURIComponent(u);}
function me(){var x='';try{var m=JSON.parse(localStorage.getItem('cbs_me')||'null');if(m&&m.name)x=m.name;}catch(z){}if(!x){try{x=localStorage.getItem('cbs_name')||'';}catch(z){}}return x;}
function lock(on){document.body.style.overflow=on?'hidden':'';}
function dlg(h,wide){var o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg'+(wide?' wide':'')+'">'+h+'</div>';document.body.appendChild(o);lock(true);o.close=function(){o.remove();if(!document.querySelector('.ov,.lb'))lock(false);};return o;}
/* in-app confirm: resolves true/false */
function ask(title,msg,ok,danger){return new Promise(function(res){var o=dlg('<h2>'+e(title)+'</h2><div class="m">'+msg+'</div><div class="b"><button class="btn'+(danger?' red':'')+'" id="aY">'+e(ok||'OK')+'</button><button class="btn ghost" id="aN">Cancel</button></div>');
 o.querySelector('#aY').onclick=function(){o.close();res(true);};o.querySelector('#aN').onclick=function(){o.close();res(false);};o.addEventListener('click',function(ev){if(ev.target===o){o.close();res(false);}});});}
function tell(title,msg){var o=dlg('<h2>'+e(title)+'</h2><div class="m">'+msg+'</div><div class="b"><button class="btn" id="tk">OK</button></div>');o.querySelector('#tk').onclick=o.close;}
function view(u){var o=document.createElement('div');o.className='lb';o.innerHTML='<img src="'+img(u)+'" alt=""><button class="btn ghost">Close</button>';document.body.appendChild(o);lock(true);o.onclick=function(ev){if(ev.target.tagName!=='IMG'){o.remove();if(!document.querySelector('.ov,.lb'))lock(false);}};}
function load(){return fetch('/webhook/cbs-service-data?job='+encodeURIComponent(JOB),{cache:'no-store'}).then(function(r){return r.json();}).then(function(d){if(!d||!d.ok)throw 0;X=d;
 document.getElementById('sub').textContent=[X.name,X.site,X.client].filter(Boolean).join(' \u00b7 ')||'Chelmsford Building Services';}).catch(function(){X=null;app.innerHTML='<div class="empty">Could not load the job. Refresh to try again.</div>';throw 0;});}
function nPhotos(sh){var n=0;(sh.sections||[]).forEach(function(c){GROUPS.forEach(function(g){n+=((c.photos||{})[g[0]]||[]).length;});});return n;}
/* ---------- list ---------- */
function list(){CUR=null;DIRTY=false;var L=X.sheets||[],h='';
 h+='<div class="tools"><button class="btn" id="nw">+ New service sheet</button></div>';
 if(!L.length)h+='<div class="empty">No service sheets on this job yet.<br>A service sheet records the completed works with before, work in progress and after photos, signed off by CBS.</div>';
 L.forEach(function(sh){var secs=(sh.sections||[]).map(function(c){return c.title;}).filter(Boolean);
  h+='<div class="card"><div class="t">'+e(sh.sheet_no)+' \u00b7 '+e(dmy(sh.sheet_date))+'<span class="tag '+(sh.pdf_url?'ok':'dr')+'">'+(sh.pdf_url?'PDF saved':'Draft')+'</span></div>'
  +'<div class="m">'+(secs.length?e(secs.join(' \u00b7 ')):'No description yet')+'</div>'
  +'<div class="m">'+(sh.sections||[]).length+' section'+((sh.sections||[]).length===1?'':'s')+' \u00b7 '+nPhotos(sh)+' photo'+(nPhotos(sh)===1?'':'s')+(sh.signed_by?' \u00b7 Signed by '+e(sh.signed_by):'')+(sh.updated_at?' \u00b7 Updated '+e(dmy(sh.updated_at))+(sh.updated_by?' by '+e(sh.updated_by):''):'')+'</div>'
  +'<div class="b"><button class="btn sm" data-ed="'+sh.id+'">Open</button>'+(sh.pdf_url?'<a class="btn ghost sm" href="/webhook/cbs-file?u='+encodeURIComponent(sh.pdf_url)+'" target="_blank" rel="noopener">View PDF</a>':'')+'<button class="btn red sm" data-dl="'+sh.id+'">Delete</button></div></div>';});
 app.innerHTML=h;
 document.getElementById('nw').onclick=function(){edit(null);};
 [].forEach.call(app.querySelectorAll('[data-ed]'),function(b){b.onclick=function(){edit(+b.getAttribute('data-ed'));};});
 [].forEach.call(app.querySelectorAll('[data-dl]'),function(b){b.onclick=function(){del(+b.getAttribute('data-dl'),b);};});}
function del(id,btn){var sh=(X.sheets||[]).filter(function(x){return x.id===id;})[0];if(!sh)return;
 ask('Delete '+sh.sheet_no+'?','This deletes the service sheet record from the hub.'+(sh.pdf_url?' The saved PDF stays in the job\u2019s files.':''),'Delete','1').then(function(ok){if(!ok)return;
  return ask('Are you sure?','Delete service sheet '+e(sh.sheet_no)+' on job '+e(JOB)+'. This cannot be undone.','Yes, delete it','1').then(function(ok2){if(!ok2||BUSY)return;BUSY=true;btn.disabled=true;btn.textContent='Deleting\u2026';
   return fetch('/webhook/cbs-service-del',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job:JOB,id:id,by:me()})}).then(function(r){if(!r.ok)throw 0;return r.json();}).then(function(d){if(!d||!d.ok)throw 0;BUSY=false;return load().then(list);})
   .catch(function(){BUSY=false;btn.disabled=false;btn.textContent='Delete';tell('Not deleted','Could not delete the service sheet. Check your connection and try again.');});});});}
/* ---------- editor ---------- */
function blankSec(){return {title:'',details:'',photos:{before:[],progress:[],after:[]}};}
function edit(id){var sh=id?(X.sheets||[]).filter(function(x){return x.id===id;})[0]:null;
 if(sh)CUR=JSON.parse(JSON.stringify(sh));
 else{var sig=(X.sigs||[]).filter(function(x){return x.name.toLowerCase()===me().toLowerCase();})[0];
  CUR={id:0,tok:'t'+Date.now()+Math.random().toString(36).slice(2,8),sheet_no:'',sheet_date:today(),location:X.address||X.site||'',job_title:JOB+(X.name?' - '+X.name:''),sections:[blankSec()],signed_by:sig?sig.name:''};}
 CUR.sections=(CUR.sections&&CUR.sections.length?CUR.sections:[blankSec()]).map(function(c){c.photos=c.photos||{};GROUPS.forEach(function(g){c.photos[g[0]]=c.photos[g[0]]||[];});return c;});
 DIRTY=!id;draw();window.scrollTo(0,0);}
function draw(){var C=CUR,h='';
 h+='<div class="card"><h3>'+(C.sheet_no?e(C.sheet_no):'New service sheet')+(C.pdf_url?'<span class="tag ok">PDF saved</span>':'<span class="tag dr">Draft</span>')+'</h3>'
 +'<div class="g3"><div><label class="f">Date</label><input class="i" type="date" id="fDate" value="'+e(C.sheet_date)+'"></div><div><label class="f">Location</label><input class="i" id="fLoc" spellcheck="true" value="'+e(C.location)+'"></div><div><label class="f">Job</label><input class="i" id="fJob" spellcheck="true" value="'+e(C.job_title)+'"></div></div></div>';
 C.sections.forEach(function(c,i){
  h+='<div class="card sec" data-i="'+i+'"><h3>Section '+(i+1)+'<span class="sp"></span>'+(i?'<button class="btn ghost sm" data-up="'+i+'" title="Move up">\u2191</button>':'')+(i<C.sections.length-1?'<button class="btn ghost sm" data-dn="'+i+'" title="Move down">\u2193</button>':'')+(C.sections.length>1?'<button class="btn red sm" data-rm="'+i+'">Remove section</button>':'')+'</h3>'
  +'<label class="f">Description</label><input class="i" data-k="title" data-i="'+i+'" spellcheck="true" placeholder="e.g. Replace damaged fire door to plant room" value="'+e(c.title)+'">'
  +'<label class="f">Details</label><textarea class="i" data-k="details" data-i="'+i+'" spellcheck="true" placeholder="What was done, materials used, anything the client should know">'+e(c.details)+'</textarea>';
  GROUPS.forEach(function(g){var L=c.photos[g[0]];
   h+='<div class="pg"><div class="pgh">'+g[1]+' photos <span>'+(L.length?L.length:'none')+'</span><span style="flex:1"></span><button class="btn ghost sm" data-add="'+i+'" data-g="'+g[0]+'">+ Add photos</button></div>';
   if(L.length)h+='<div class="th">'+L.map(function(p,pi){return '<div class="tc"><img loading="lazy" src="'+img(p.u)+'" data-vw="'+e(p.u)+'" alt=""><div class="mv">'+(pi?'<button data-pl="'+i+'|'+g[0]+'|'+pi+'" title="Move left">\u2190</button>':'')+(pi<L.length-1?'<button data-pr="'+i+'|'+g[0]+'|'+pi+'" title="Move right">\u2192</button>':'')+'</div><button class="x" data-px="'+i+'|'+g[0]+'|'+pi+'" title="Remove from this sheet">\u00d7</button><input data-cap="'+i+'|'+g[0]+'|'+pi+'" placeholder="Caption (optional)" spellcheck="true" value="'+e(p.cap)+'"></div>';}).join('')+'</div>';
   h+='</div>';});
  h+='</div>';});
 h+='<div class="tools"><button class="btn ghost" id="addSec">+ Add section</button></div>';
 var SG=X.sigs||[];
 h+='<div class="card"><h3>Signed / serviced</h3>'+(SG.length?'<select class="i" id="fSig"><option value="">Choose who signs this sheet</option>'+SG.map(function(x){return '<option'+(x.name===C.signed_by?' selected':'')+'>'+e(x.name)+'</option>';}).join('')+(C.signed_by&&!SG.some(function(x){return x.name===C.signed_by;})?'<option selected>'+e(C.signed_by)+'</option>':'')+'</select><div class="sig" id="sigP"></div>'
  :'<div class="m">No saved signatures yet. Add one in the Operations Hub under Settings \u203a Signatures, then refresh this page.</div>')
  +'<div class="note">Signatures come from Settings \u203a Signatures in the Operations Hub.</div></div>';
 h+='<div class="bar"><button class="btn ghost" id="bk">Back to service sheets</button><button class="btn ghost" id="sv">Save draft</button><button class="btn" id="pdf">Save and create PDF</button></div>';
 app.innerHTML=h;
 sigPrev();wire();}
function sigPrev(){var p=document.getElementById('sigP');if(!p)return;var x=(X.sigs||[]).filter(function(z){return z.name===CUR.signed_by;})[0];p.innerHTML=x&&x.img?'<img src="'+e(x.img)+'" alt="Signature"><span class="m">'+e(x.name)+(x.role?' \u00b7 '+e(x.role):'')+'</span>':(CUR.signed_by?'<span class="m">No signature image saved for '+e(CUR.signed_by)+'.</span>':'');}
function pk(v){var a=s(v).split('|');return {i:+a[0],g:a[1],p:+a[2]};}
function wire(){
 document.getElementById('fDate').onchange=function(){CUR.sheet_date=this.value;DIRTY=true;};
 document.getElementById('fLoc').oninput=function(){CUR.location=this.value;DIRTY=true;};
 document.getElementById('fJob').oninput=function(){CUR.job_title=this.value;DIRTY=true;};
 [].forEach.call(app.querySelectorAll('[data-k]'),function(el){el.oninput=function(){CUR.sections[+el.getAttribute('data-i')][el.getAttribute('data-k')]=el.value;DIRTY=true;};});
 [].forEach.call(app.querySelectorAll('[data-cap]'),function(el){el.oninput=function(){var x=pk(el.getAttribute('data-cap'));CUR.sections[x.i].photos[x.g][x.p].cap=el.value;DIRTY=true;};});
 [].forEach.call(app.querySelectorAll('[data-vw]'),function(el){el.onclick=function(){view(el.getAttribute('data-vw'));};});
 [].forEach.call(app.querySelectorAll('[data-px]'),function(el){el.onclick=function(){var x=pk(el.getAttribute('data-px'));CUR.sections[x.i].photos[x.g].splice(x.p,1);DIRTY=true;keep(draw);};});
 [].forEach.call(app.querySelectorAll('[data-pl],[data-pr]'),function(el){el.onclick=function(){var l=el.hasAttribute('data-pl'),x=pk(el.getAttribute(l?'data-pl':'data-pr')),L=CUR.sections[x.i].photos[x.g],t=x.p+(l?-1:1),m=L[x.p];L[x.p]=L[t];L[t]=m;DIRTY=true;keep(draw);};});
 [].forEach.call(app.querySelectorAll('[data-up],[data-dn]'),function(el){el.onclick=function(){var u=el.hasAttribute('data-up'),i=+el.getAttribute(u?'data-up':'data-dn'),t=i+(u?-1:1),L=CUR.sections,m=L[i];L[i]=L[t];L[t]=m;DIRTY=true;draw();};});
 [].forEach.call(app.querySelectorAll('[data-rm]'),function(el){el.onclick=function(){var i=+el.getAttribute('data-rm'),c=CUR.sections[i],n=0;GROUPS.forEach(function(g){n+=c.photos[g[0]].length;});
  if(!c.title&&!c.details&&!n){CUR.sections.splice(i,1);DIRTY=true;draw();return;}
  ask('Remove section '+(i+1)+'?','Its description, details and '+n+' photo'+(n===1?'':'s')+' come off this sheet. The photos stay on the ServiceM8 job.','Remove section','1').then(function(ok){if(!ok)return;CUR.sections.splice(i,1);DIRTY=true;draw();});};});
 [].forEach.call(app.querySelectorAll('[data-add]'),function(el){el.onclick=function(){picker(+el.getAttribute('data-add'),el.getAttribute('data-g'));};});
 document.getElementById('addSec').onclick=function(){CUR.sections.push(blankSec());DIRTY=true;draw();var L=app.querySelectorAll('.sec');if(L.length)L[L.length-1].scrollIntoView({behavior:'smooth',block:'start'});};
 var sg=document.getElementById('fSig');if(sg)sg.onchange=function(){CUR.signed_by=this.value;DIRTY=true;sigPrev();};
 document.getElementById('bk').onclick=function(){if(!DIRTY){list();return;}ask('Leave without saving?','Your changes to this service sheet have not been saved.','Leave without saving','1').then(function(ok){if(ok)list();});};
 document.getElementById('sv').onclick=function(){save(false);};
 document.getElementById('pdf').onclick=function(){save(true);};}
function keep(fn){var y=window.pageYOffset;fn();window.scrollTo(0,y);}
/* ---------- photo picker (job's ServiceM8 photos, filtered by category) ---------- */
function picker(si,gk){var g=GROUPS.filter(function(x){return x[0]===gk;})[0],P=X.photos||[],sel={},flt=P.some(function(p){return p.cats.indexOf(g[2])>-1;})?g[2]:'all';
 var used={};GROUPS.forEach(function(x){CUR.sections[si].photos[x[0]].forEach(function(p){used[p.u]=x[1];});});
 if(!P.length){tell('No photos yet','There are no photos on the ServiceM8 job yet. Photos the team take on the job in ServiceM8 show here.');return;}
 var o=dlg('<h2>Add '+e(g[1].toLowerCase())+' photos \u00b7 Section '+(si+1)+'</h2><div class="chips" id="pc"></div><div class="pk" id="pg"></div><div class="note">Categories are set on the job page photo sorter. Faded photos are already in this section.</div><div class="b"><button class="btn" id="pa" disabled>Add photos</button><button class="btn ghost" id="px">Cancel</button><span class="m" id="pn"></span></div>',true);
 function shown(p){if(flt==='all')return true;if(flt==='unsorted')return !p.cats.length;return p.cats.indexOf(flt)>-1;}
