function e(t){return s(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function dmy(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:s(d);}
function longDate(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return s(d);var M=['January','February','March','April','May','June','July','August','September','October','November','December'];return m[3]+' '+M[+m[2]-1]+' '+m[1];}
function today(){var d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
function img(u){return '/webhook/cbs-job-photo?u='+encodeURIComponent(u);}
