 [].forEach.call(app.querySelectorAll('[data-pl],[data-pr]'),function(el){el.onclick=function(){var l=el.hasAttribute('data-pl'),x=pk(el.getAttribute(l?'data-pl':'data-pr')),L=CUR.sections[x.i].photos[x.g],t=x.p+(l?-1:1),m=L[x.p];L[x.p]=L[t];L[t]=m;DIRTY=true;keep(draw);};});
 [].forEach.call(app.querySelectorAll('[data-up],[data-dn]'),function(el){el.onclick=function(){var u=el.hasAttribute('data-up'),i=+el.getAttribute(u?'data-up':'data-dn'),t=i+(u?-1:1),L=CUR.sections,m=L[i];L[i]=L[t];L[t]=m;DIRTY=true;draw();};});
 [].forEach.call(app.querySelectorAll('[data-rm]'),function(el){el.onclick=function(){var i=+el.getAttribute('data-rm'),c=CUR.sections[i],n=0;GROUPS.forEach(function(g){n+=c.photos[g[0]].length;});
  if(!c.title&&!c.details&&!n){CUR.sections.splice(i,1);DIRTY=true;draw();return;}
