/* ---------- photo picker (job's ServiceM8 photos, filtered by category) ---------- */
function picker(si,gk){var g=GROUPS.filter(function(x){return x[0]===gk;})[0],P=X.photos||[],sel={},flt=P.some(function(p){return p.cats.indexOf(g[2])>-1;})?g[2]:'all';
 var used={};GROUPS.forEach(function(x){CUR.sections[si].photos[x[0]].forEach(function(p){used[p.u]=x[1];});});
 if(!P.length){tell('No photos yet','There are no photos on the ServiceM8 job yet. Photos the team take on the job in ServiceM8 show here.');return;}
 var o=dlg('<h2>Add '+e(g[1].toLowerCase())+' photos \u00b7 Section '+(si+1)+'</h2><div class="chips" id="pc"></div><div class="pk" id="pg"></div><div class="note">Categories are set on the job page photo sorter. Faded photos are already in this section.</div><div class="b"><button class="btn" id="pa" disabled>Add photos</button><button class="btn ghost" id="px">Cancel</button><span class="m" id="pn"></span></div>',true);
 function shown(p){if(flt==='all')return true;if(flt==='unsorted')return !p.cats.length;return p.cats.indexOf(flt)>-1;}
 function chip(k,l,n){return '<button class="chip'+(flt===k?' on':'')+'" data-f="'+e(k)+'">'+e(l)+' <span>'+n+'</span></button>';}
 function rd(){var h=chip('all','All',P.length);['Before','Progress','After'].forEach(function(c){h+=chip(c,c==='Progress'?'Work in progress':c,P.filter(function(p){return p.cats.indexOf(c)>-1;}).length);});
  var oth={};P.forEach(function(p){p.cats.forEach(function(c){if(['Before','Progress','After'].indexOf(c)<0)oth[c]=(oth[c]||0)+1;});});Object.keys(oth).forEach(function(c){h+=chip(c,c,oth[c]);});
  h+=chip('unsorted','Unsorted',P.filter(function(p){return !p.cats.length;}).length);o.querySelector('#pc').innerHTML=h;
  var L=P.filter(shown);o.querySelector('#pg').innerHTML=L.length?L.map(function(p){return '<div class="pt'+(sel[p.u]?' on':'')+(used[p.u]?' used':'')+'" data-u="'+e(p.u)+'"><img loading="lazy" src="'+img(p.u)+'" alt=""><div class="ck">'+(sel[p.u]?'\u2713':'')+'</div><div class="cs">'+(p.ts?'<span>'+e(dmy(p.ts))+'</span>':'')+p.cats.map(function(c){return '<span>'+e(c)+'</span>';}).join('')+(used[p.u]?'<span>In '+e(used[p.u]).toLowerCase()+'</span>':'')+'</div></div>';}).join(''):'<div class="m">No photos in this category.</div>';
  var n=Object.keys(sel).length;o.querySelector('#pa').disabled=!n;o.querySelector('#pa').textContent=n?'Add '+n+' photo'+(n===1?'':'s'):'Add photos';o.querySelector('#pn').textContent=n?n+' selected':'';
