 rd();o.querySelector('#px').onclick=o.close;o.addEventListener('click',function(ev){if(ev.target===o)o.close();});
 o.querySelector('#pa').onclick=function(){var L=CUR.sections[si].photos[gk],have={};L.forEach(function(p){have[p.u]=1;});
  P.forEach(function(p){if(sel[p.u]&&!have[p.u])L.push({u:p.u,cap:p.cap||''});});DIRTY=true;o.close();keep(draw);};}
/* ---------- save ---------- */
function payload(){return {sheet_date:CUR.sheet_date,location:CUR.location,job_title:CUR.job_title,signed_by:CUR.signed_by,
 sections:CUR.sections.map(function(c){var o={title:s(c.title).trim(),details:s(c.details).trim(),photos:{}};GROUPS.forEach(function(g){o.photos[g[0]]=c.photos[g[0]].map(function(p){return {u:p.u,cap:s(p.cap).trim()};});});return o;})};}
function setBar(t){var a=document.getElementById('sv'),b=document.getElementById('pdf'),k=document.getElementById('bk');[a,b,k].forEach(function(x){if(x)x.disabled=!!t;});if(t&&b)b.textContent=t;else if(b)b.textContent='Save and create PDF';}
function save(withPdf){if(BUSY)return;var P=payload(),by=me();
 if(!by){tell('Sign in first','Sign in to the Operations Hub so the service sheet is saved under your name.');return;}
 if(withPdf){var hasAny=P.sections.some(function(c){return c.title||c.details;});
  if(!hasAny){tell('Nothing to put on the sheet','Add a description or details to at least one section first.');return;}
  if(!P.signed_by){tell('Choose who signs','Choose who signs the sheet under Signed / serviced.');return;}
  if(!window.jspdf){tell('PDF tool not loaded','The PDF tool did not load. Refresh the page and try again.');return;}}
 BUSY=true;setBar(withPdf?'Saving\u2026':'Saving');
 fetch('/webhook/cbs-service-save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job:JOB,id:CUR.id||0,tok:CUR.tok||'',by:by,sheet:P})}).then(function(r){if(!r.ok)throw 0;return r.json();})
 .then(function(d){if(!d||!d.ok)throw new Error(d&&d.message||'');CUR.id=d.id;CUR.sheet_no=d.sheet_no;DIRTY=false;
  if(!withPdf){BUSY=false;return load().then(function(){edit(CUR.id);});}
  setBar('Building the PDF\u2026');
  return build(P,function(t){setBar(t);}).then(function(doc){setBar('Saving the PDF to the job\u2026');var name=fname();
   return fetch('/webhook/cbs-service-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job:JOB,id:CUR.id,by:by,b64:doc.output('datauristring')})}).then(function(r){if(!r.ok)throw 0;return r.json();})
    .then(function(x){if(!x||!x.ok)throw 0;doc.save(name);BUSY=false;return load().then(function(){list();tell('Service sheet saved',e(CUR.sheet_no||'The service sheet')+' is saved to the job\u2019s files (Service Sheets) and has downloaded to this device.');});})
    .catch(function(){doc.save(name);BUSY=false;setBar('');tell('PDF not saved to the job','The PDF downloaded, but it could not be saved to the job\u2019s files. Press Save and create PDF again.');});});})
 .catch(function(err){BUSY=false;setBar('');tell('Not saved','Could not save the service sheet'+(err&&err.message?': '+e(err.message):'')+'. Check your connection and try again.');});}
function fname(){return 'Job '+JOB+' - Service sheet '+(CUR.sheet_no||'')+' - '+s(CUR.sheet_date||today())+'.pdf';}
/* ---------- PDF (CBS service sheet layout) ---------- */
function getLogo(){if(LOGO!==null)return Promise.resolve(LOGO);return fetch('/webhook/cbs-programme-logo').then(function(r){return r.json();}).then(function(d){LOGO=(d&&d.lg)||'';return LOGO;}).catch(function(){LOGO='';return '';});}
function imgData(u){return fetch(img(u)).then(function(r){if(!r.ok)throw 0;return r.blob();}).then(function(bl){return new Promise(function(res){var url=URL.createObjectURL(bl),im=new Image();
 im.onload=function(){var mx=1400,sc=Math.min(1,mx/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*sc));c.height=Math.max(1,Math.round(im.height*sc));var g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);g.drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(url);res({d:c.toDataURL('image/jpeg',0.78),w:c.width,h:c.height});};
 im.onerror=function(){URL.revokeObjectURL(url);res(null);};im.src=url;});}).catch(function(){return null;});}
function build(P,say){return getLogo().then(function(lg){var U=[];P.sections.forEach(function(c){GROUPS.forEach(function(g){c.photos[g[0]].forEach(function(p){if(U.indexOf(p.u)<0)U.push(p.u);});});});
 var IM={},done=0;say(U.length?'Loading photos (0 of '+U.length+')\u2026':'Building the PDF\u2026');
 return U.reduce(function(pr,u){return pr.then(function(){return imgData(u).then(function(d){IM[u]=d;done++;say('Loading photos ('+done+' of '+U.length+')\u2026');});});},Promise.resolve()).then(function(){say('Building the PDF\u2026');return make(P,lg,IM);});});}
function make(P,lg,IM){var jsPDF=window.jspdf.jsPDF,doc=new jsPDF({unit:'mm',format:'a4'}),W=210,HH=297,M=13,CW=W-2*M,y=0,FOOT=HH-27,LBL=27,OR=[255,199,128];
 var sig=(X.sigs||[]).filter(function(z){return z.name===P.signed_by;})[0];
 function head(first){if(lg){try{var pr=doc.getImageProperties(lg),hh=first?17:11,ww=pr.width*hh/pr.height;if(ww>62){ww=62;hh=pr.height*ww/pr.width;}doc.addImage(lg,'PNG',M,first?9:7,ww,hh);}catch(z){}}
